def owner_session(session=Depends(session_from_header)): if session.user.role is not Role.OWNER: raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="owner authorization required") return session
def _client_ip(req: Request) -> str: forwarded = req.headers.get("x-forwarded-for") if forwarded: return forwarded.split(",")[0].strip() return req.client.host if req.client else "127.0.0.1"
def _check_cooldown(tracker, key: str) -> None: is_locked, cooldown = tracker.is_locked_out(key) if is_locked: raise HTTPException( status_code=429, detail=f"RATE_LIMIT_COOLDOWN: Cooldown active for {cooldown}s", headers={"Retry-After": str(cooldown)}, )
class _NullLimiter: def is_locked_out(self, key: str): return False, 0 def record_failure(self, key: str): return False, 0 def record_success(self, key: str) -> None: return None def clear(self, key: str) -> None: return None def record_request(self, key: str, max_requests=None, window_seconds: int = 60): return False, 0
_NULL_LIMITER = _NullLimiter()
def _auth_limiter(name: str): # P2-02/BUG-006: uniform non-optional guard; missing policy/limiter # degrades to a no-op limiter instead of AttributeError. try: policy = getattr(app.state, "auth_policy", None) if policy is None: return _NULL_LIMITER lim = getattr(policy, name, None) return lim if lim is not None else _NULL_LIMITER except Exception: return _NULL_LIMITER
