def _verified_mtls(request: Request) -> bool: try: return bool(app.state.mtls_authority.verified(request)) except Exception: return False
def session_from_header(authorization: str | None = Header(default=None)): token = authorization.removeprefix("Bearer ").strip() if authorization else None try: return session_service.require(token) except SecurityError as exc: raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="authentication required") from exc
