ity_store, governance_store=governance_store, artifact_root=artifact_root or Path("users"), dataset_feed=_dataset_feed) if security_store is not None else None) if app.state.paper_service is not None and getattr(app.state.paper_service, "_dataset_feed", None) is None and _dataset_feed is not None: app.state.paper_service._dataset_feed = _dataset_feed # R-05: manual walk-forward/OOS productization around paper replay. app.state.walkforward_service = ( WalkForwardService(security_store=security_store, backtest_service=app.state.backtest_service, paper_service=app.state.paper_service) if security_store is not None and app.state.backtest_service is not None else None ) # F-21 canonical historical-data lifecycle (product runtime storage # authority). Charting, import, inventory and coverage resolve here. app.state.historical_data_service = historical_data_service app.state.orders_portfolio_service = ( OrdersPortfolioService(app.state.paper_service, live_readiness=app.state.live_readiness_service) if app.state.paper_service is not None else None ) # P1-A (R-07): persistent deployment orchestration over canonical authorities. # State management only — no execution handle beyond the paper service # reference used for runtime-session ownership checks. No broker handle exists. app.state.deployment_service = ( DeploymentService( security_store=security_store, governance_store=governance_store, artifact_root=artifact_root or Path("users"), paper_service=app.state.paper_service, ) if security_store is not None else None ) # This is process-wired rather than request-derived. Until a deployment # supplies authoritative TLS or proven trusted-edge evidence, reject all # mTLS assertions rather than trusting a caller-controlled HTTP header. app.state.mtls_authority = mtls_authority or RejectingMtlsAuthority()
