def _verified_mtls(request: Request) -> bool: try: return bool(app.state.mtls_authority.verified(request)) except Exception: return False
def session_from_header(authorization: str | None = Header(default=None)): token = authorization.removeprefix("Bearer ").strip() if authorization else None try: return session_service.require(token) except SecurityError as exc: raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="authentication required") from exc
def mutable_session(session=Depends(session_from_header)): try: return session_service.require(session.token, mutable=True) except SecurityError as exc: raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="step-up authentication required") from exc
def owner_session(session=Depends(session_from_header)): if session.user.role is not Role.OWNER: raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="owner authorization required") return session
def _client_ip(req: Request) -> str: forwarded = req.headers.get("x-forwarded-for") if forwarded: return forwarded.split(",")[0].strip() return req.client.host if req.client else "127.0.0.1"
def _check_cooldown(tracker, key: str) -> None: is_locked, cooldown = tracker.is_locked_out(key) if is_locked: raise HTTPException( status_code=429, detail=f"RATE_LIMIT_COOLDOWN: Cooldown active for {cooldown}s", headers={"Retry-After": str(cooldown)}, )
class _NullLimiter: def is_locked_out(self, key: str): return False, 0 def record_failure(self, key: str): return False, 0 def record_success(self, key: str) -> None: return None def clear(self, key: str) -> None: return None def record_request(self, key: str, max_requests=None, window_seconds: int = 60): return False, 0
_NULL_LIMITER = _NullLimiter()
def _auth_limiter(name: str): # P2-02/BUG-006: uniform non-optional guard; missing policy/limiter # degrades to a no-op limiter instead of AttributeError. try: policy = getattr(app.state, "auth_policy", None) if policy is None: return _NULL_LIMITER lim = getattr(policy, name, None) return lim if lim is not None else _NULL_LIMITER except Exception: return _NULL_LIMITER
def _check_expensive_throttle(user_id: str | UUID) -> None: if not hasattr(app.state, "auth_policy") or app.state.auth_policy is None: return key = f"expensive:{str(user_id)}" throttled, rem = app.state.auth_policy.expensive_limiter.record_request(key, max_requests=30, window_seconds=60) if throttled: raise HTTPException( status_code=429, detail=f"RATE_LIMIT_EXCEEDED: Too many requests. Retry after {rem}s", headers={"Retry-After": str(rem)}, )
def live_authority(): if app.state.live_readiness_service is None: raise HTTPException(503, "LIVE_AUTHORITY_UNAVAILABLE") return app.state.live_readiness_service
def live_call(method, *args): try: return method(*args) except LiveAuthorityUnavailable: raise HTTPException(503, "CORE_AUDIT_UNAVAILABLE") from None except LiveExecutionDisabled: raise HTTPException(403, "EXECUTION_DISABLED") from None
def bind_canonical_user_authority(service, user_id: str) -> bool: # NF-R203-04: resolve the session user's canonical user_connections # record before any operational use. Best-effort: False keeps honest # UNCONFIGURED truth; no process-global credential is ever consulted. try: return service.bind_operational_connection( str(user_id), security_store=app.state.security_store, credential_provider=None) except Exception: return False
@app.get("/api/v1/user/live-readiness") def user_live_readiness(session=Depends(session_from_header), service=Depends(live_authority)): bind_canonical_user_authority(service, str(session.user.user_id)) return service.readiness(str(session.user.user_id))
@app.post("/api/v1/user/live-readiness/refresh") def refresh_live_readiness(session=Depends(session_from_header), service=Depends(live_authority)): bind_canonical_user_authority(service, str(session.user.user_id)) return live_call(service.refresh, str(session.user.user_id))
@app.post("/api/v1/user/live-readiness/intents") def validate_live_intent(body: LiveIntentValidationRequest, session=Depends(session_from_header), service=Depends(live_authority)): bind_canonical_user_authority(service, str(session.user.user_id)) return live_call(service.validate, str(session.user.user_id), body.model_dump())
